from __future__ import annotations

import typing
import pytest

from llm_router._internal.providers.retry import (
    build_provider_retrying,
    is_retryable_provider_error,
)

pytestmark = pytest.mark.verification_kind("unit")


class _DummyRetryLogger:
    """Minimal dummy logger fulfilling RetryLogger duck-typing."""

    def debug(self, *args: typing.Any, **kwargs: typing.Any) -> None:
        pass

    def info(self, *args: typing.Any, **kwargs: typing.Any) -> None:
        pass

    def warning(self, *args: typing.Any, **kwargs: typing.Any) -> None:
        pass

    def error(self, *args: typing.Any, **kwargs: typing.Any) -> None:
        pass

    def exception(self, *args: typing.Any, **kwargs: typing.Any) -> None:
        pass

    def log(self, *args: typing.Any, **kwargs: typing.Any) -> None:
        pass

    def bind(self, *args: typing.Any, **kwargs: typing.Any) -> _DummyRetryLogger:
        return self


def _build_retry_policy(max_attempts: int = 3) -> typing.Any:
    """Construct a RetryPolicy instance using the project's own type."""
    try:
        from llm_router._internal.providers.retry import RetryPolicy
    except (ImportError, AttributeError):
        from llm_router import RetryPolicy  # type: ignore[attr-defined]

    try:
        return RetryPolicy(
            max_attempts=max_attempts,
            min_wait_seconds=0.0,
            max_wait_seconds=0.0,
        )
    except Exception:
        try:
            policy = RetryPolicy(max_attempts=max_attempts)
            for attr in ("min_wait_seconds", "max_wait_seconds"):
                if hasattr(policy, attr):
                    try:
                        object.__setattr__(policy, attr, 0.0)
                    except Exception:
                        pass
            return policy
        except Exception:
            policy = RetryPolicy()
            for attr, val in (
                ("max_attempts", max_attempts),
                ("min_wait_seconds", 0.0),
                ("max_wait_seconds", 0.0),
            ):
                try:
                    object.__setattr__(policy, attr, val)
                except Exception:
                    pass
            return policy


def _get_retryable_provider_error() -> Exception:
    """Find or construct a retryable provider error recognized by is_retryable_provider_error."""
    candidates: list[type] = []

    # Check globals of the retry module where is_retryable_provider_error is defined
    for val in is_retryable_provider_error.__globals__.values():
        if isinstance(val, type) and issubclass(val, BaseException) and val not in (BaseException, Exception):
            if val not in candidates:
                candidates.append(val)
        elif isinstance(val, (tuple, list, set)):
            for item in val:
                if isinstance(item, type) and issubclass(item, BaseException) and item not in (BaseException, Exception):
                    if item not in candidates:
                        candidates.append(item)

    # Check llm_router.exceptions if present
    try:
        import llm_router.exceptions as exc_mod
        for name in dir(exc_mod):
            val = getattr(exc_mod, name)
            if isinstance(val, type) and issubclass(val, BaseException) and val not in (BaseException, Exception):
                if val not in candidates:
                    candidates.append(val)
    except (ImportError, AttributeError):
        pass

    # Check test support module if present
    try:
        import tests.llm_router.support.workers.retry as worker_retry
        for name in dir(worker_retry):
            val = getattr(worker_retry, name)
            if isinstance(val, type) and issubclass(val, BaseException) and val not in (BaseException, Exception):
                if val not in candidates:
                    candidates.append(val)
            elif callable(val) and ("error" in name.lower() or "exception" in name.lower()):
                try:
                    obj = val()
                    if isinstance(obj, BaseException) and is_retryable_provider_error(obj):
                        return obj
                except Exception:
                    pass
    except (ImportError, AttributeError):
        pass

    # Try instantiating candidate classes with standard provider error shapes
    for cls in candidates:
        instantiators = [
            lambda c: c(),
            lambda c: c("Rate limit exceeded"),
            lambda c: c("Rate limit exceeded", retryable=True),
            lambda c: c(message="Rate limit exceeded", retryable=True),
            lambda c: c("Rate limit exceeded", is_retryable=True),
            lambda c: c(message="Rate limit exceeded", is_retryable=True),
            lambda c: c("Rate limit exceeded", provider="test-provider", retryable=True),
            lambda c: c(message="Rate limit exceeded", provider="test-provider", retryable=True),
            lambda c: c(status_code=429),
            lambda c: c("Rate limit exceeded", status_code=429),
            lambda c: c(message="Rate limit exceeded", status_code=429),
            lambda c: c("Service unavailable", status_code=503),
            lambda c: c(message="Service unavailable", status_code=503),
        ]
        for inst in instantiators:
            try:
                err = inst(cls)
                if is_retryable_provider_error(err):
                    return err
                for flag in ("retryable", "is_retryable"):
                    try:
                        setattr(err, flag, True)
                        if is_retryable_provider_error(err):
                            return err
                    except Exception:
                        pass
            except Exception:
                continue

    # Fallback to subclassing candidate base exception or Exception
    for base_cls in candidates + [Exception]:
        class _DynamicRetryableProviderError(base_cls):  # type: ignore[valid-type, misc]
            retryable = True
            is_retryable = True
            status_code = 429
            provider = "test-provider"

        for inst in [
            lambda: _DynamicRetryableProviderError("Rate limit exceeded"),
            lambda: _DynamicRetryableProviderError(),
            lambda: _DynamicRetryableProviderError(message="Rate limit exceeded"),
        ]:
            try:
                err = inst()
                if is_retryable_provider_error(err):
                    return err
            except Exception:
                continue

    raise RuntimeError("Failed to construct a retryable provider error")


@pytest.mark.verifies("TREQ_PROVIDER_RETRY_BOUNDS[revision==1]")
def test_sync_retrying_reraises_original_provider_exception_on_exhaustion() -> None:
    """Verify that retrying reraises the original provider exception instead of RetryError."""
    max_attempts = 3
    policy = _build_retry_policy(max_attempts=max_attempts)
    logger = _DummyRetryLogger()

    retrying = build_provider_retrying(policy=policy, logger=logger)
    error_instance = _get_retryable_provider_error()
    assert is_retryable_provider_error(error_instance) is True

    attempt_count = 0

    def failing_provider_call() -> typing.NoReturn:
        nonlocal attempt_count
        attempt_count += 1
        raise error_instance

    with pytest.raises(BaseException) as exc_info:
        retrying(failing_provider_call)

    assert not type(exc_info.value).__name__.endswith("RetryError"), (
        f"Expected original provider error to be reraised, but got {type(exc_info.value).__name__}"
    )
    assert exc_info.value is error_instance
    assert type(exc_info.value) is type(error_instance)
    assert attempt_count == max_attempts
